// Example of validating additional properties in a JSON object
function validateAdditionalProperties($data) {
    foreach ($data as $key => $value) {
        if (!is_string($value)) {
            return false;
        }
    }
    return true;
}

// Example usage
$productData = json_decode('{"color": "red", "size": "M"}', true);
assert(validateAdditionalProperties($productData) === true);
